import React, { useTransition } from 'react';

const App = () => {
  const [isLoading, setIsLoading] = React.useState(false);
  const [isPending, startTransition] = useTransition();

  const loadData = () => {
    setIsLoading(true);
    setTimeout(() => {
      setIsLoading(false);
    }, 1000);
  };

  const handleLoadWithTransition = () => {
    startTransition(() => {
      loadData();
    });
  };

  const handleLoadWithoutTransition = () => {
    loadData();
  };

  return (
    <div>
      <p>Loading: {isLoading ? 'Yes' : 'No'}</p>
      <p>Pending: {isPending ? 'Yes' : 'No'}</p>
      <button onClick={handleLoadWithoutTransition}>Load without Transition</button>
      <button onClick={handleLoadWithTransition}>Load with Transition</button>
    </div>
  );
};

